"""人が記述した制作案。戦闘データ・画像生成コードではない。"""
FAMILIES = []

def F(fid, region, motif, ecology, palette, face, anatomy, connection, role, contrast, stages, *, rarity='uncommon', time='all', field=(), evolve=(), acquire_gates=(), notes='中：器官の付け根と色面を三面で一致させる。'):
    FAMILIES.append(dict(id=fid, region=region, motif=motif, ecology=ecology,
        palette=palette.split('／'), face=face, anatomy=anatomy, connection=connection,
        role=role, contrast=contrast, stages=stages, rarity=rarity, time=time,
        field=list(field), evolve=list(evolve), acquire_gates=list(acquire_gates), notes=notes))

def S(name, types, silhouette, mark, change, move, tactic, **kw):
    return dict(name=name, types=types.split('/'), silhouette=silhouette, mark=mark,
        change=change, move=move, tactic=tactic, **kw)

